import{c as a,Q as r,j as t,m as s}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Harness-MU: A Safe, Governed, and Effective Harness for Multi-User LLM Agents","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.21856","title":"Harness-MU: A Safe, Governed, and Effective Harness for Multi-User LLM Agents","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2606.21856,"authors":["Wangxuan Fan","Xiaoyu Nie","Zhongxiang Dai"],"domains":["cs.CR","cs.AI"],"html":"https://arxiv.org/html/2606.21856v1","pdf_path":"pdfs/2606.21856.pdf","published_date":"2026-06-20T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-20-harness-mu-multi-user-llm-agents-2606-21856.md","filePath":"research/papers/2026-06-20-harness-mu-multi-user-llm-agents-2606-21856.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-06-20-harness-mu-multi-user-llm-agents-2606-21856.md"};function o(i,e,l,c,u,h){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="harness-mu-a-safe-governed-and-effective-harness-for-multi-user-llm-agents" tabindex="-1">Harness-MU: A Safe, Governed, and Effective Harness for Multi-User LLM Agents <a class="header-anchor" href="#harness-mu-a-safe-governed-and-effective-harness-for-multi-user-llm-agents" aria-label="Permalink to &quot;Harness-MU: A Safe, Governed, and Effective Harness for Multi-User LLM Agents&quot;">​</a></h1><p><strong>Authors</strong>: Wangxuan Fan, Xiaoyu Nie, Zhongxiang Dai <strong>Published</strong>: June 20, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.21856" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.21856</a> · <a href="https://arxiv.org/html/2606.21856v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.21856 <strong>Categories</strong>: cs.CR, cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.21856" target="_blank" rel="noreferrer">research/papers/pdfs/2606.21856.pdf</a> (15 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>The increasing deployment of large language model (LLM) agents in collaborative workflows demands robust multi-user, multi-principal interaction mechanisms capable of enforcing access permissions, resolving authoritative conflicts, and preventing unauthorized data disclosure. However, a fundamental mismatch exists between the single-user training paradigm of contemporary LLMs and the hard constraints required for multi-principal governance, rendering probabilistic, prompt-based safeguards vulnerable under multi-turn adversarial [interactions]. Our key insight is that governance constraints -- who is authorized, what is restricted, and whose instructions take precedence -- are deterministic runtime variables that should be enforced by execution hooks rather than entrusted to the LLM. We present Harness-MU, the first model-agnostic, zero-tuning infrastructure framework for multi-user LLM agents. By decoupling language generation from safety orchestration, Harness-MU guarantees unbreakable permission boundaries while maximizing compliant demand satisfaction. Across four frontier open-weight and proprietary models on the Muses-Bench benchmark, Harness-MU achieves the goal of privacy preservation across all access-control attacks, outperforming the standard baseline by 0.28--0.39 in utility score and improving instruction-following accuracy by up to 48.9 percentage points.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><p>核心洞見：<strong>治理約束（誰被授權 / 什麼受限 / 誰的指令優先）是確定性 runtime 變數，應由 execution hook 強制，而非交給 LLM</strong>。Harness-MU = 首個 model-agnostic、zero-tuning 的多使用者 LLM agent infra 框架：</p><ul><li><strong>解耦 language generation 與 safety orchestration</strong> → 保證「不可破壞的權限邊界」同時最大化合規需求滿足。</li><li>對抗多輪 adversarial：prompt-based safeguard 在多輪攻擊下脆弱，故把硬約束移出 LLM。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>在 <strong>Muses-Bench</strong> 上，跨 4 個 frontier（開源權重 + 專有）模型，於<strong>所有 access-control 攻擊</strong>達成隱私保全。</li><li>utility score 超基線 <strong>0.28–0.39</strong>。</li><li>instruction-following 準確度提升最多 <strong>48.9 個百分點</strong>。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>文件未含明確 limitation 章節；zero-tuning 對更複雜 principal hierarchy 的擴展性待驗。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>直接驗證 core.md 跨切紀律「判斷 vs 決定」</strong>：「治理約束 = 確定性 runtime 變數，交 execution hook 不交 LLM」幾乎是本 workspace「硬性執行交 hooks，規則 advisory」的論文化重述——強背書。</li><li><strong>Agent Input Security 對齊</strong>：與 <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md）「外部輸入當 data 不當 instruction（allowlist）」同源；Harness-MU 的 permission boundary = allowlist 心智模型的執行層落地。</li><li><strong>與 SafeHarness / Harness-MU / AOHP 共構「安全 harness」子線</strong>：可納入 harness-meta 安全稽核時的對照基準。</li><li>⚠️ 場景為多 principal 協作；本 workspace 多為單使用者，價值在「hook-enforced 確定性約束」的設計論證，而非 benchmark 數字直接套用。</li></ul>',17)])])}const p=a(n,[["render",o]]);export{g as __pageData,p as default};
